app = Flask(__name__)

@app.route("/normal", methods=["GET"])
def normal():
    dc = request.args.get('dc')
    username = request.args.get('username')

    if not dc or not username:
        return jsonify({"error": "Domain Component and username are required"}), 400

    try:
        server = ldap3.Server('localhost')
        conn = ldap3.Connection(server, auto_bind=True)

        search_filter = f"(&(objectClass=user)(sAMAccountName={username}))"
        search_base = f"dc={dc},dc=com"

        conn.search(search_base, search_filter, attributes=['cn', 'mail'])

        if conn.entries:
            user_info = conn.entries[0]
            return jsonify({"name": user_info.cn.value, "email": user_info.mail.value}), 200
        else:
            return jsonify({"error": "User not found"}), 404

    except ldap3.LDAPException as e:
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            conn.unbind()

